@echo off
setlocal enabledelayedexpansion
set KILLEXE=taskkill.exe /F /PID
set KILLPARAM="authserver"
set port=26306

echo service is %KILLPARAM%


echo %KILLPARAM%
for /f "tokens=1-5" %%a in ('netstat -ano ^|find ":%port%"') do (
	echo %%e
	if "%%e" =="" (
		set pid=%%d
	) else (
		echo no
		set pid=%%e
	)
	echo !pid!
	%KILLEXE% !pid!
	pause
)

